00009      Shader::Shader(const char* vertexPath, const char* fragmentPath)
00010     {
00011         // 1. retrieve the vertex/fragment source code from filePath
00012         std::string vertexCode;
00013         std::string fragmentCode;
00014         std::ifstream vShaderFile;
00015         std::ifstream fShaderFile;
00016         // ensure ifstream objects can throw exceptions:
00017         vShaderFile.exceptions(std::ifstream::failbit | std::ifstream::badbit);
00018         fShaderFile.exceptions(std::ifstream::failbit | std::ifstream::badbit);
00019         try
00020         {
00021             // open files
00022             vShaderFile.open(vertexPath);
00023             fShaderFile.open(fragmentPath);
00024             std::stringstream vShaderStream, fShaderStream;
00025             // read file's buffer contents into streams
00026             vShaderStream << vShaderFile.rdbuf();
00027             fShaderStream << fShaderFile.rdbuf();
00028             // close file handlers
00029             vShaderFile.close();
00030             fShaderFile.close();
00031             // convert stream into string
00032             vertexCode = vShaderStream.str();
00033             fragmentCode = fShaderStream.str();
00034         }
00035         catch (std::ifstream::failure& e)
00036         {
00037             std::cout << "ERROR::SHADER::FILE_NOT_SUCCESSFULLY_READ: " << e.what() << std::endl;
00038         }
00039         const char* vShaderCode = vertexCode.c_str();
00040         const char* fShaderCode = fragmentCode.c_str();
00041         // 2. compile shaders
00042         unsigned int vertex, fragment;
00043         // vertex shader
00044         vertex = glCreateShader(GL_VERTEX_SHADER);
00045         glShaderSource(vertex, 1, &vShaderCode, NULL);
00046         glCompileShader(vertex);
00047         checkCompileErrors(vertex, "VERTEX");
00048         // fragment Shader
00049         fragment = glCreateShader(GL_FRAGMENT_SHADER);
00050         glShaderSource(fragment, 1, &fShaderCode, NULL);
00051         glCompileShader(fragment);
00052         checkCompileErrors(fragment, "FRAGMENT");
00053         // shader Program
00054         ID = glCreateProgram();
00055         glAttachShader(ID, vertex);
00056         glAttachShader(ID, fragment);
00057         glLinkProgram(ID);
00058         checkCompileErrors(ID, "PROGRAM");
00059         // delete the shaders as they're linked into our program now and no longer necessary
00060         glDeleteShader(vertex);
00061         glDeleteShader(fragment);
00062 
00063     }
