00092      Shader::Shader(VertexShader vertexshader, FragmentShader frgmentshader, GeometryShader geometryshader)
00093      {
00094          const char* vShaderCode = vertexshader.ShaderCode.c_str();
00095          const char* fShaderCode = frgmentshader.ShaderCode.c_str();
00096          const char* gshderCode = geometryshader.ShaderCode.c_str();
00097          // 2. compile shaders
00098          unsigned int vertex, fragment,geometry;
00099          // vertex shader
00100          vertex = glCreateShader(GL_VERTEX_SHADER);
00101          glShaderSource(vertex, 1, &vShaderCode, NULL);
00102          glCompileShader(vertex);
00103          checkCompileErrors(vertex, "VERTEX");
00104          // fragment Shader
00105          fragment = glCreateShader(GL_FRAGMENT_SHADER);
00106          glShaderSource(fragment, 1, &fShaderCode, NULL);
00107          glCompileShader(fragment);
00108          checkCompileErrors(fragment, "FRAGMENT");
00109          //geometry Shder
00110          geometry = glCreateShader(GL_GEOMETRY_SHADER);
00111          glShaderSource(geometry, 1, &gshderCode, NULL);
00112          glCompileShader(geometry);
00113          checkCompileErrors(geometry, "GEOMETRY");
00114          // shader Program
00115          ID = glCreateProgram();
00116          glAttachShader(ID, vertex);
00117          glAttachShader(ID, fragment);
00118          glAttachShader(ID, geometry);
00119          glLinkProgram(ID);
00120          checkCompileErrors(ID, "PROGRAM");
00121          // delete the shaders as they're linked into our program now and no longer necessary
00122          glDeleteShader(vertex);
00123          glDeleteShader(fragment);
00124          glDeleteShader(geometry);
00125      }
