00221      void Shader::checkCompileErrors(GLuint shader, std::string type)
00222     {
00223         GLint success;
00224         GLchar infoLog[1024];
00225         if (type != "PROGRAM")
00226         {
00227             glGetShaderiv(shader, GL_COMPILE_STATUS, &success);
00228             if (!success)
00229             {
00230                 glGetShaderInfoLog(shader, 1024, NULL, infoLog);
00231                 std::cout << "ERROR::SHADER_COMPILATION_ERROR of type: " << type << "\n" << infoLog << "\n -- --------------------------------------------------- -- " << std::endl;
00232             }
00233         }
00234         else
00235         {
00236             glGetProgramiv(shader, GL_LINK_STATUS, &success);
00237             if (!success)
00238             {
00239                 glGetProgramInfoLog(shader, 1024, NULL, infoLog);
00240                 std::cout << "ERROR::PROGRAM_LINKING_ERROR of type: " << type << "\n" << infoLog << "\n -- --------------------------------------------------- -- " << std::endl;
00241             }
00242         }
00243     }
