00270      ShaderU::ShaderU(char* vertexPath, char* fragmentPath) {
00271         std::string vertexCode;
00272         std::string fragmentCode;
00273         std::ifstream vShaderFile;
00274         std::ifstream fShaderFile;
00275         vShaderFile.open(vertexPath);
00276         fShaderFile.open(fragmentPath);
00277         std::stringstream vShaderStream, fShaderStream;
00278 
00279         if (vShaderFile.good() && fShaderFile.good()) {
00280             vShaderStream << vShaderFile.rdbuf();
00281             fShaderStream << fShaderFile.rdbuf();
00282             vShaderFile.close();
00283             fShaderFile.close();
00284             vertexCode = vShaderStream.str();
00285             fragmentCode = fShaderStream.str();
00286             const char* vShaderCode = vertexCode.c_str();
00287             const char* fShaderCode = fragmentCode.c_str();
00288             textcount = fShaderCode[2];
00289             unsigned int vertex, fragment;
00290             vertex = glCreateShader(GL_VERTEX_SHADER);
00291             glShaderSource(vertex, 1, &vShaderCode, NULL);
00292             glCompileShader(vertex);
00293             checkCompileErrors(vertex, "VERTEX");
00294             fragment = glCreateShader(GL_FRAGMENT_SHADER);
00295             glShaderSource(fragment, 1, &fShaderCode, NULL);
00296             glCompileShader(fragment);
00297             checkCompileErrors(fragment, "FRAGMENT");
00298             ID = glCreateProgram();
00299             glAttachShader(ID, vertex);
00300             glAttachShader(ID, fragment);
00301             glLinkProgram(ID);
00302             checkCompileErrors(ID, "PROGRAM");
00303             glDeleteShader(vertex);
00304             glDeleteShader(fragment);
00305 
00306         }
00307 
00308     }
